sql:
SELECT TIMESTAMP_DIFF(endtime, starttime, SECOND) AS incision_duration
FROM procedureevents_mv
WHERE subject_id = 22180 AND hadm_id = 162436 AND itemid IN (
    SELECT itemid FROM d_items WHERE label LIKE '%incision%'
);

SELECT dose_val_rx, dose_unit_rx 
FROM prescriptions 
WHERE subject_id = 31038 AND hadm_id = 174978 AND LOWER(drug) LIKE '%insomnia%';
